// Builds src/theme/prime-sky.css from PrimeNG 17's Aura light theme, swapping its
// blue accent for sky (sky-700 passes WCAG AA with white text; the stock blue-500 does not).
// Runs on postinstall, so the generated file is never committed.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const source = join(root, 'node_modules', 'primeng', 'resources', 'themes', 'aura-light-blue', 'theme.css');
const outDir = join(root, 'src', 'theme');
const out = join(outDir, 'prime-sky.css');

const swaps = {
  '#3b82f6': '#0369a1', // primary
  '#2563eb': '#075985', // hover
  '#1d4ed8': '#075985', // highlight text
  '#eff6ff': '#f0f9ff', // highlight background
  '#f5f9ff': '#f0f9ff', '#d0e1fd': '#e0f2fe', '#abc9fb': '#bae6fd', '#85b2f9': '#7dd3fc',
  '#609af8': '#38bdf8', '#326fd1': '#0284c7', '#295bac': '#0369a1', '#204887': '#075985', '#183462': '#0c4a6e',
};

let css = readFileSync(source, 'utf8');
for (const [from, to] of Object.entries(swaps)) css = css.replace(new RegExp(from, 'gi'), to);
css = css.replace(/rgba\(59, 130, 246,/g, 'rgba(3, 105, 161,');
// Fonts stay in node_modules; point the url()s back at them from the new location.
const fonts = relative(outDir, join(dirname(source), 'fonts')).split('\\').join('/');
css = css.replace(/url\("\.\/fonts\//g, `url("${fonts}/`);

mkdirSync(outDir, { recursive: true });
writeFileSync(out, `/* Generated by scripts/build-theme.mjs from ${relative(root, source)}. Do not edit. */\n${css}`);
console.log(`theme: wrote ${relative(root, out)}`);
